#include <string>
#include <sstream>
#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    string sortSentence(string s) {
        stringstream ss(s);
        string word;
        vector<string> words(10);
        while (ss >> word) {
            int pos = word.back() - '0';
            word.pop_back();
            words[pos - 1] = word;
        }

        string res;
        for (const string& w : words) {
            if (w.empty()) break;
            if (!res.empty()) res += " ";
            res += w;
        }
        return res;
    }
};
